{"command":"python3 - << 'PY'
import chess, chess.engine
fen = "r1b2rk1/p1n1pp2/3p2p1/q4PPp/Np1QP2P/1P6/P1P1B3/2KR3R b - - 0 20"
e = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")
try:
    e.configure({"Threads": 4, "Hash": 512})
except Exception as ex:
    print("cfg", ex)
info = e.analyse(chess.Board(fen), chess.engine.Limit(time=20), multipv=6)
if isinstance(info, dict):
    info = [info]
for i in info:
    pv = " ".join(m.uci() for m in i.get("pv", [])[:18])
    print(i["score"].white(), "d", i.get("depth"), pv)
e.quit()
PY"}

